$isAccountSettingsPage = realpath((string) ($_SERVER['SCRIPT_FILENAME'] ?? ''))
    === realpath(__DIR__ . '/account.php');
authRequire(false, ['ACADEMIC_OFFICE'], $isAccountSettingsPage);
require_once __DIR__.'/shared-functions.php';
function acadLayout(string $title):void {
 $name=acadH($_SESSION['auth_username']??'Academic Office');$csrf=acadH(authCsrf());$page=basename($_SERVER['SCRIPT_NAME']??'');
 $links=['dashboard.php'=>['Dashboard','▦'],'preview-review.php'=>['Preview Requests','▤'],'history.php'=>['Approval History','◷'],'exam-requests.php'=>['Exam Approvals','▣']];
 echo '<!doctype html><html lang="en"><head><link rel="icon" type="image/png" href="../assets/images/BCP_LOGO.png?v=20261121b"><link rel="shortcut icon" type="image/png" href="../assets/images/BCP_LOGO.png?v=20261121b"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.acadH($title).' | BCP Academic Office</title><link rel="stylesheet" href="assets/office.css?v=9"><link rel="stylesheet" href="assets/admin-consistency.css?v=10"><link rel="stylesheet" href="assets/academic-notifications.css?v=1"><link rel="stylesheet" href="assets/ao-confirm.css?v=2"></head><body class="acad-shell"><div class="layout"><aside class="acad-sidebar" id="acadSidebar"><div class="brand"><img src="../assets/images/BCP_LOGO.png" alt="BCP logo"><button class="acad-bell" id="acadBell" type="button" aria-label="Open notifications" aria-expanded="false" aria-controls="acadNotificationPanel" title="Notifications"><svg viewBox="0 0 24 24" width="21" height="21" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></svg><span id="acadBellCount" class="acad-bell-count" hidden>0</span></button></div><div class="acad-side-heading"><b>Main Navigation</b><small>General</small></div><nav><a class="'.($page==='dashboard.php'?'active':'').'" href="dashboard.php"><span class="acad-nav-symbol">◉</span> Dashboard</a></nav><div class="acad-side-heading acad-mod-heading"><b>Academic Modules</b><small>Reviews &amp; Approvals</small></div><nav>';
 foreach($links as $href=>$item) {if($href==='dashboard.php')continue;echo '<a class="'.($page===$href?'active':'').'" href="'.$href.'"><span class="acad-nav-symbol">'.$item[1].'</span> '.acadH($item[0]).'</a>';}
 echo '<a class="'.($page==='account.php'?'active':'').'" href="account.php"><span class="acad-nav-symbol">⚙</span> Account Settings</a></nav><div class="sidefoot"><form method="post" action="../../logout.php"><input type="hidden" name="csrf_token" value="'.$csrf.'"><button type="submit">↪ &nbsp; Logout</button></form></div></aside><div class="main"><header class="acad-topbar"><button type="button" class="menu acad-hamburger" aria-label="Toggle sidebar" aria-expanded="true" onclick="document.body.classList.toggle(\'acad-sidebar-hidden\');this.setAttribute(\'aria-expanded\',!document.body.classList.contains(\'acad-sidebar-hidden\'))">☰</button><span class="acad-topbar-spacer"></span><span class="role">♙ &nbsp; ACADEMIC OFFICE</span><a class="acad-avatar" href="account.php" aria-label="Account Settings" title="Account Settings">'.acadH(strtoupper(substr((string)($_SESSION['auth_username']??'A'),0,1))).'</a></header><main class="acad-content">';
}
function acadEnd():void{echo '</main></div></div><section id="acadNotificationPanel" class="acad-notification-panel" aria-label="Academic Office notifications" hidden><div class="acad-notification-head"><div><strong>Notifications</strong><small id="acadNotificationSummary">Loading...</small></div><button type="button" id="acadMarkAll">Mark all as read</button></div><div id="acadNotificationItems" class="acad-notification-items"></div></section><script>window.BCP_ACAD_NOTIFICATIONS={api:'.json_encode(authBasePath().'/app/api/notifications.php').',csrf:'.json_encode(authCsrf()).'};</script><script src="assets/academic-notifications.js?v=1" defer></script><script src="assets/ao-confirm.js?v=2" defer></script></body></html>';}
